// Мини-уроки по математике (темы m.*). Формат - в index.js.

import { L, same } from '../../pools/gen.js';

// Короткая запись: тексты - массивы [en, ru, kk] (один элемент - одинаково везде), готовые L/same тоже допустимы.
const t = (a) => (Array.isArray(a) ? (a.length === 1 ? same(a[0]) : L(a[0], a[1], a[2])) : a);
// Варианты сдвигаются по кругу (сдвиг зависит от текста правила), чтобы верный ответ не всегда стоял на одном месте.
const les = (rule, points, q, steps, cq, opts, answer, why) => {
  const k = rule[0].length % opts.length;
  const options = opts.map((_, i) => t(opts[(i - k + opts.length) % opts.length]));
  return {
    rule: t(rule),
    points: points.map(t),
    example: { q: t(q), steps: steps.map(t) },
    check: { q: t(cq), options, answer: (answer + k) % opts.length, why: t(why) },
  };
};

